mapper.select:
SELECT COUNT(*)                                                                           AS callCount,
       SUM(CASE WHEN answer_flag = 0 THEN 1 ELSE 0 END)                                   AS answeredCount,
       SUM(CASE WHEN answer_flag = 0 THEN TIMESTAMPDIFF(SECOND, answer_time, call_end_time) ELSE 0 END) AS totalDurationSec,
       SUM(CASE WHEN transfer_human = 1 THEN 1 ELSE 0 END)                                AS aiTransferToMe
FROM call_record
WHERE del_flag = 0
  AND agent_id = #{agentId}
  AND call_start_time >= #{begin}
  AND call_start_time < #{end}
